@startuml

enum PriorityScore {
  HIGH
  LOW
}

class HospitalHouseMD {}

class Patient {
  + consentSigned : boolean
}

class Doctor {
  + approveDiagnosis(diagnosis: Diagnosis)
  + downgradeTreatment(treatment: Treatment)
}

class Nurse {}

class Illness {
  + priorityScore : PriorityScore
}

class Diagnosis {
  + Id : string
}

class Treatment {
  + stage : int
}

class TreatmentForm {
  + signedDate : date
}

HospitalHouseMD "1" -- "*" Illness
HospitalHouseMD "1" -- "*" Diagnosis
HospitalHouseMD "1" -- "*" Treatment

Illness "1" -- "*" Diagnosis
Illness "1" -- "*" Treatment : priority upgrade

Diagnosis "1" -- "*" Treatment
Diagnosis "0..*" -- "1" Doctor : made by
Diagnosis "0..*" -- "1" Doctor : approved by

Patient "1" -- "*" Doctor : assigned to
Patient "1" -- "*" Treatment : undergoes
Patient "1" -- "0..1" TreatmentForm : signs

Treatment "0..*" -- "0..*" Doctor : monitored by
Treatment "0..*" -- "0..*" Nurse : monitored by

@enduml

